"""Hand-authored source-bound L22 drafts; no independent-review claims."""
from authoring_helpers import DraftBatch,formula
b=DraftBatch('W05-L22',5,'L22','Modeling and control of a single joint',669,'robotics-integration-author-L22')
gear='Rigid ideal reduction gear with η=ω_motor/ω_load>1; load-coordinate inertia I and damping b; motor inertia I_m and damping b_m.'
elec=formula('L_A di_A/dt=v_A−r_A i_A−k_e ω_m',{'L_A':'armature inductance','i_A':'armature current','v_A':'applied armature voltage','r_A':'armature resistance','k_e':'back-EMF constant','ω_m':'motor angular speed','t':'time'},{'L_A':'H','i_A':'A','v_A':'V','r_A':'Ω','k_e':'V/(rad/s)','ω_m':'rad/s','t':'s'})
eq=formula('J=I+η²I_m; B=b+η²b_m; J θddot+B θdot=ητ_m',{'J,I,I_m':'effective load, load and motor inertia','B,b,b_m':'effective load, load and motor viscous damping','η':'motor/load speed ratio','θ':'load angle','θdot,θddot':'load angular velocity and acceleration','τ_m':'motor electromagnetic torque'},{'J,I,I_m':'kg·m²','B,b,b_m':'N·m·s/rad','η':'dimensionless','θ':'rad','θdot':'rad/s','θddot':'rad/s²','τ_m':'N·m'},[gear])
b.add(672,'model-scope','State the rotary-joint model scope','What is the safe scope of the introductory second-order single-joint model?', ['A rotary joint driven by a DC motor under the stated simplifications','Every possible manipulator joint, including every prismatic and flexible joint, without modification','Only a mathematical angle with no inertia or actuator dynamics','A universal proof that all electrical and mechanical robot dynamics have exactly two states'],0,'The lecture develops a simplified rotary-joint model; retaining electrical inductance or flexible modes can increase its order.',['This is the modeled system and its qualification.','Other joint types and flexibility need different or additional dynamics.','The model includes inertia and an actuator.','Model order depends on retained states.'],difficulty='easy')
b.add(672,'robot-figure-dof','Count only the illustrated arm joints','The robot figure labels shoulder 3 DOF, elbow 1 DOF, wrist 3 DOF, hand 4 DOF and neck 3 DOF; how many DOF belong to shoulder, elbow and wrist together?', ['7','11','10','14'],0,'The specified arm joints contribute 3+1+3=7; hand and neck are explicitly outside this count.',['This sums the requested three joint groups.','This additionally counts the hand.','This additionally counts the neck.','This counts arm, hand and neck together.'],typ='diagram',difficulty='easy',assumptions=['Count the labels in this figure, not a universal number for robot arms.'])
b.add(673,'motor-parts','Match the brushed-motor component roles','Which role assignment matches the brushed DC motor description?', ['Stator: stationary field structure; armature: rotating current-carrying part; commutator: switches current connection during rotation','Stator: rotating armature; armature: fixed output gear; commutator: measures joint position','Stator: torque sensor; armature: speed reducer; commutator: supplies the permanent magnetic field','Stator: switches brush connections; armature: stationary encoder; commutator: the output shaft bearing'],0,'The field structure, rotating armature and mechanical current switching are distinct components; the encoder and gearhead have separate functions.',['These are the operating roles described in the source.','This exchanges stationary and rotating roles and assigns the encoder function to the commutator.','This confuses sensing, gearing and field generation.','This exchanges several distinct components.'],typ='match',difficulty='easy',conflict='The slide heading associates ironless winding with the stator while its armature description concerns the rotating current-carrying winding; this question tests the unambiguous component roles, not that questionable placement label.')
b.add(673,'commutation','Distinguish commutation from irreversible rotation','Why does the commutator switch the armature current connections as a brushed motor rotates?', ['To maintain torque in the same rotational sense for the chosen supply polarity','To make the motor unable to reverse under any applied voltage','To convert the encoder angle directly into a gear ratio','To eliminate the need for any magnetic field'],0,'Commutation coordinates current direction with rotor position; it does not prohibit reversal when the drive polarity is changed.',['This is the torque-maintenance role.','Direction can be reversed by an appropriate drive change.','Angle sensing and gear geometry are different functions.','The magnetic field is essential to electromagnetic force.'],difficulty='easy')
b.add(673,'lorentz-force','Calculate a magnetic-force vector','For a charge q=2 C moving with v=(3,0,0) m/s in B=(0,4,0) T, what is the magnetic force q(v×B)?', ['(0,0,24) N','(0,0,−24) N','(24,0,0) N','(0,0,12) N'],0,'The right-handed cross product is v×B=(0,0,12), and multiplying by q=2 gives 24 N along positive z.',['This includes the correct direction and charge multiplier.','This reverses the cross-product order.','Magnetic force is perpendicular to both specified vectors.','This omits the charge multiplier.'],typ='numerical',assumptions=['The values are a hypothetical arithmetic example, not measured motor parameters.'],steps=['Compute 3×4=12 along +z.','Multiply by q=2 C to obtain 24 N.'],formulas=[formula('F=q(v×B)',{'F':'magnetic force','q':'electric charge','v':'charge velocity','B':'magnetic flux density'},{'F':'N','q':'C','v':'m/s','B':'T'})])
b.add(673,'lorentz-force','Check the zero-force alignment','For a nonzero charge and nonzero magnetic field, which velocity gives zero magnetic force in the stated Lorentz law?', ['A velocity parallel or antiparallel to the magnetic field','Any velocity perpendicular to the magnetic field','Only a velocity whose magnitude equals the field magnitude numerically','Every velocity if the charge is negative'],0,'The cross-product magnitude contains sin of the angle, which is zero for parallel or antiparallel vectors.',['Both alignments make the cross product zero.','Perpendicular alignment maximizes magnitude for fixed magnitudes.','The numerical equality compares unlike quantities and is irrelevant.','Negative charge reverses direction, not generally magnitude.'],difficulty='easy')
b.add(674,'motor-laws','Apply the torque-current and back-EMF laws','A motor has k_m=0.4 N·m/A and k_e=0.2 V/(rad/s); at i_A=3 A and ω_m=10 rad/s, which torque and back EMF follow?', ['1.2 N·m and 2 V','0.8 N·m and 3 V','7.5 N·m and 50 V','1.2 N·m and 0.02 V'],0,'Torque equals k_m i_A=1.2 N·m, while back EMF equals k_e ω_m=2 V.',['Both products follow the stated laws.','This incorrectly mixes the given quantities.','This divides by the constants instead of multiplying.','The torque is right but the back-EMF computation divides by speed.'],typ='numerical',formulas=[formula('τ_m=k_m i_A; v_e=k_e ω_m',{'τ_m':'electromagnetic motor torque','k_m':'torque constant','i_A':'armature current','v_e':'back EMF','k_e':'back-EMF constant','ω_m':'motor speed'},{'τ_m':'N·m','k_m':'N·m/A','i_A':'A','v_e':'V','k_e':'V/(rad/s)','ω_m':'rad/s'})])
b.add([674,675],'back-emf-feedback','Predict the electrical effect of increasing speed','With applied voltage, resistance and instantaneous current fixed, what does a rise in positive motor speed do to di_A/dt in the displayed circuit model with L_A>0?', ['It reduces di_A/dt because the opposing back EMF increases','It increases di_A/dt because back EMF adds to the supply','It leaves di_A/dt unchanged because back EMF depends only on current','It changes only the gear ratio and not the circuit'],0,'The term −k_e ω_m reduces the voltage available across the inductance when speed rises in the stated positive direction.',['This follows the negative back-EMF term.','The displayed sign is opposing, not aiding.','The model makes back EMF proportional to angular speed.','The effect is electrical and does not change gear geometry.'],typ='scenario',assumptions=['k_e>0 and the source sign convention applies.'],formulas=[elec])
b.add(675,'armature-circuit','Read the series circuit balance','Which equation matches the displayed armature resistance, inductance and opposing back EMF?', ['L_A di_A/dt+r_A i_A=v_A−k_e ω_m','L_A i_A+r_A di_A/dt=v_A−k_e ω_m','L_A di_A/dt+r_A i_A=v_A+k_e ω_m','L_A di_A/dt+r_A i_A=k_e v_A−ω_m'],0,'Inductor voltage is L_A di_A/dt, resistor voltage is r_A i_A, and back EMF is subtracted from the applied voltage.',['This is the stated voltage balance.','This exchanges the inductor and resistor constitutive relations.','This reverses the opposing back-EMF sign.','The last expression combines inconsistent quantities.'],typ='diagram',difficulty='easy',formulas=[elec])
b.add(675,'armature-circuit','Calculate the current derivative','Given v_A=12 V, r_A=2 Ω, i_A=1 A, k_e=0.1 V/(rad/s), ω_m=20 rad/s and L_A=0.5 H, what is di_A/dt?', ['16 A/s','20 A/s','24 A/s','4 A/s'],0,'The resistor and back EMF each use 2 V, leaving 8 V across 0.5 H, so the derivative is 16 A/s.',['This subtracts both voltage drops before dividing by inductance.','This omits one 2 V drop.','This omits both opposing drops.','This multiplies by inductance instead of dividing.'],typ='numerical',steps=['Compute r_A i_A=2 V and k_e ω_m=2 V.','Compute (12−2−2)/0.5=16 A/s.'],formulas=[elec])
b.add(675,'inductance-continuity','Infer current continuity without promising an ideal driver','What follows from L_A>0 and bounded applied voltage, speed and resistance current drop?', ['Armature current cannot jump instantaneously in this model','Armature current follows every commanded step with zero delay','Motor position jumps whenever a current command changes','The torque constant becomes zero during every transient'],0,'Finite voltage across nonzero inductance gives a finite current derivative, so a discontinuous current jump is not supported.',['This is the continuity consequence of the circuit equation.','Real current regulation has finite electrical and drive limits.','The electrical statement does not create a position jump.','No time-varying torque constant is introduced.'],typ='scenario',formulas=[elec])
b.add([675,691],'current-driver-scope','State when electrical inductance can be neglected','Which condition best supports neglecting armature inductance in a reduced mechanical model?', ['The relevant electrical/current-loop response is much faster than the mechanical motion being modeled','Inductance is nonzero, so its effect must always be exactly zero','The gear ratio exceeds one, regardless of electrical and mechanical time scales','The armature current changes faster than any finite driver can track'],0,'The reduction is a time-scale approximation or a suitable current-control approximation, not a universal consequence of using a DC motor.',['This justifies a reduced-order model over the intended bandwidth.','Nonzero inductance can matter, especially during fast current transients.','Gearing alone does not establish the electrical time-scale separation.','This would undermine the approximation rather than justify it.'],typ='scenario',assumptions=['The summary explicitly says that inductance may be neglected under simplifying assumptions; retained electrical dynamics require an additional state.'])
b.add(676,'gear-power','Relate ideal gear speed and port torque','For an ideal reduction with η=10, an input port speed of 20 rad/s and an input port torque of 2 N·m, what are the corresponding output port speed and torque?', ['2 rad/s and 20 N·m','200 rad/s and 0.2 N·m','2 rad/s and 0.2 N·m','200 rad/s and 20 N·m'],0,'A reduction divides output speed by η and multiplies output port torque by η, preserving ideal port power at 40 W.',['Both ratios and ideal power agree.','This describes the inverse ratio.','This divides both quantities and loses the ideal power balance.','This multiplies both and creates an impossible ideal power gain.'],typ='numerical',assumptions=['The given input port torque is torque transmitted into the ideal gear, not a motor electromagnetic torque already consumed by motor losses.'],formulas=[formula('ω_out=ω_in/η; τ_out=ητ_in; τ_outω_out=τ_inω_in',{'ω_out,ω_in':'gear output and input angular speed','τ_out,τ_in':'gear output and input transmitted torque','η':'input/output speed ratio'},{'ω_out,ω_in':'rad/s','τ_out,τ_in':'N·m','η':'dimensionless','power':'W'})])
b.add(676,'reflected-coordinate','Choose the load-coordinate effective dynamics','Which load-coordinate equation follows from the ideal rigid gear and the given motor and load inertias and damping?', ['ητ_m=(I+η²I_m)θddot+(b+η²b_m)θdot','τ_m/η=(I+I_m/η²)θddot+(b+b_m/η²)θdot','ητ_m=(I+ηI_m)θddot+(b+ηb_m)θdot','τ_m=(η²I+I_m)θddot+(η²b+b_m)θdot'],0,'Because motor angle is η times load angle, referring motor inertia and damping to the load multiplies them by η²; the generalized input torque becomes ητ_m.',['All terms use the same load coordinate.','This applies inverse reflection while still claiming load coordinates.','The reflected inertia and damping scale quadratically, not linearly.','This mixes motor-coordinate coefficients with load derivatives.'],typ='derivation',assumptions=[gear],formulas=[eq])
b.add(676,'reflected-coordinate','Translate the same dynamics into motor coordinates','Which effective inertia and damping act on motor-coordinate speed and acceleration?', ['I_m+I/η² and b_m+b/η²','I+η²I_m and b+η²b_m','I_m+η²I and b_m+η²b','I_m+I/η and b_m+b/η'],0,'Load inertia and damping reflected back to the faster motor coordinate are divided by the squared ratio.',['These are the motor-coordinate coefficients.','These are the load-coordinate coefficients.','This uses the wrong direction of reflection.','The energy and torque transformation produces η² rather than η.'],typ='derivation',assumptions=[gear],formulas=[formula('J_motor=I_m+I/η²; B_motor=b_m+b/η²',{'J_motor':'motor-coordinate effective inertia','B_motor':'motor-coordinate effective damping','I_m,I':'motor and load inertia','b_m,b':'motor and load damping','η':'motor/load speed ratio'},{'inertia':'kg·m²','damping':'N·m·s/rad','η':'dimensionless'})])
b.add(677,'gear-inertia-range','Calculate the source effective-inertia interval','The source has I from 2 to 6 kg·m², I_m=0.01 kg·m² and η=30; what is the load-coordinate effective-inertia interval?', ['11 to 15 kg·m²','2.3 to 6.3 kg·m²','1800.01 to 5400.01 kg·m²','2.000011 to 6.000011 kg·m²'],0,'The reflected motor contribution is 30²×0.01=9 kg·m², which is added to both endpoints.',['This adds the squared-ratio contribution.','This uses η rather than η².','This reflects the load in the wrong direction.','This divides the motor contribution by η².'],typ='numerical',steps=['Compute η²I_m=900×0.01=9.','Add 9 to the endpoints 2 and 6.'],formulas=[eq])
b.add(677,'inertia-variation','Distinguish absolute and relative inertia variation','When the preceding load interval 2–6 becomes the effective interval 11–15 kg·m², which statement is correct?', ['The absolute span remains 4 kg·m², while the maximum/minimum ratio decreases from 3 to 15/11','The absolute span becomes zero, so configuration no longer matters','The motor’s physical rotor inertia changes from 0.01 to 9 kg·m²','The maximum/minimum ratio remains 3 because a constant was added'],0,'Adding a constant leaves the difference unchanged but reduces the relative variation measured by this explicitly chosen ratio.',['Both the difference and the stated ratio are correct.','The span is still 4, so exact constancy is not established.','Nine is the load-referred contribution, not a physical change to the rotor.','Ratios are not invariant under adding the same nonzero constant.'],typ='scenario',assumptions=['Use maximum divided by minimum as the stated measure of relative variation.'])
b.add(677,'inertia-dominance','Qualify the large-gear-ratio approximation','When is it justified to approximate the load-coordinate effective inertia by η²I_m alone?', ['When η²I_m is much larger than I over the operating range','Whenever η>1, even if I is arbitrarily large','Whenever the motor inertia is smaller than the load inertia before reflection','Only when the load inertia is negative'],0,'Dominance depends on the reflected contribution compared with the load range, not on the gear ratio by itself.',['This directly bounds the neglected load term.','A ratio just above one need not make the motor term dominant.','The unreflected comparison alone is insufficient.','Physical inertias need not be negative for the approximation.'],typ='scenario')
b.add(678,'rigidity-assumption','Identify what the rigid model omits','Which observation most directly challenges treating the drive and link as a single rigid mechanical mode?', ['A flexible-shaft resonance lies inside the intended control bandwidth','A motor encoder reports a constant scale factor','The gearhead has a fixed known ratio','The desired position is expressed in radians'],0,'A nearby flexible mode can be excited by the controller and is not represented by the single rigid inertia–damping model.',['This is a relevant neglected dynamic mode.','A known measurement scale does not itself add flexibility.','A fixed ratio is part of the rigid model.','Radians are a coordinate unit, not an unmodeled resonance.'],typ='scenario')
b.add(679,'resonance-heuristic','Use the stated resonance-separation design rule','If the lowest unmodeled resonance is 30 rad/s, what is the largest nominal closed-loop natural frequency allowed by the slide’s half-resonance rule?', ['15 rad/s','30 rad/s','60 rad/s','7.5 rad/s'],0,'The stated heuristic is ω_n≤0.5ω_res, so the upper value under that rule is 15 rad/s.',['This applies the factor of one half once.','This uses the resonance itself without separation.','This reverses the factor.','This halves the result twice.'],typ='numerical',assumptions=['This is a heuristic bandwidth-separation rule, not a proof of stability for every flexible system.'],formulas=[formula('ω_n≤ω_res/2',{'ω_n':'chosen nominal natural frequency','ω_res':'lowest relevant unmodeled resonance frequency'},{'ω_n,ω_res':'rad/s'})])
b.add(679,'normalized-gains','Match the normalized second-order coefficients','For xddot+k_v xdot+k_p x=0 and characteristic form s²+2ζω_n s+ω_n², which gains correspond to natural frequency ω_n and damping ratio ζ?', ['k_p=ω_n² and k_v=2ζω_n','k_p=ω_n and k_v=ζ²','k_p=2ζω_n and k_v=ω_n²','k_p=1/ω_n² and k_v=1/(2ζω_n)'],0,'Matching the constant coefficient and coefficient of s gives the two stated gains.',['This matches the polynomial term by term.','The powers and dimensions do not match.','This interchanges the constant and first-order coefficients.','The coefficients are not reciprocal gains.'],typ='derivation',formulas=[formula('k_p=ω_n²; k_v=2ζω_n',{'k_p':'normalized position gain','k_v':'normalized velocity gain','ω_n':'natural frequency','ζ':'damping ratio'},{'k_p':'s⁻²','k_v':'s⁻¹','ω_n':'rad/s','ζ':'dimensionless'})])
b.add(680,'partitioned-example','Choose the critical gains in the worked example','For the source example m=b=k=1 and ω_res=8 rad/s, which normalized gains use the half-resonance rule with critical damping?', ['k_p=16 s⁻² and k_v=8 s⁻¹','k_p=64 s⁻² and k_v=16 s⁻¹','k_p=4 s⁻² and k_v=4 s⁻¹','k_p=16 s⁻² and k_v=4 s⁻¹'],0,'Choose ω_n=4 rad/s and ζ=1, yielding k_p=16 and k_v=8.',['Both the frequency rule and critical damping are satisfied.','This uses the resonance frequency rather than half of it.','This is a lower natural frequency, not the largest allowed under the stated rule.','This gives ζ=0.5 rather than critical damping.'],typ='numerical',assumptions=['Take the largest nominal natural frequency allowed by the source heuristic and ζ=1.'])
b.add(680,'partitioned-example','Evaluate the physical force after model cancellation','For xddot+xdot+x=F, use F=u+xdot+x and u=−8xdot−16x; at x=0.2 m and xdot=−0.1 m/s, what force F results?', ['−2.3 N','−2.4 N','−3.9 N','2.3 N'],0,'After cancellation terms are combined, F=−7xdot−15x=0.7−3=−2.3 N; u itself is −2.4 m/s² in the normalized interpretation.',['This includes the added damping and spring compensation.','This reports the normalized command u, not the physical force F.','This changes the velocity-term sign.','This reverses the complete control-force sign.'],typ='numerical',assumptions=['Use m=1 kg, b=1 N·s/m and k=1 N/m; the desired position and its derivatives are zero.'],steps=['Compute u=−8(−0.1)−16(0.2)=−2.4.','Add xdot+x=−0.1+0.2=0.1 to get F=−2.3 N.'])
b.add(681,'shaft-resonance','Calculate the torsional resonance','A massless elastic shaft has torsional stiffness 400 N·m/rad and attached rotational inertia 1 kg·m²; what natural angular frequency follows from the stated single-mode model?', ['20 rad/s','400 rad/s','200 rad/s','3.18 rad/s'],0,'The torsional resonance is sqrt(k_t/J)=sqrt(400/1)=20 rad/s; about 3.18 is the corresponding frequency in hertz.',['This takes the square root and retains angular-frequency units.','This omits the square root.','This divides by two rather than taking a square root.','This confuses hertz with radians per second.'],typ='numerical',formulas=[formula('ω_res=√(k_t/J); f_res=ω_res/(2π)',{'ω_res':'natural angular frequency','k_t':'torsional stiffness','J':'rotational inertia','f_res':'frequency in cycles per second'},{'ω_res':'rad/s','k_t':'N·m/rad','J':'kg·m²','f_res':'Hz'})])
b.add(681,'shaft-gains','Design normalized gains from the shaft resonance','Using the 20 rad/s shaft resonance, the half-resonance rule and critical damping, which normalized gain pair is appropriate?', ['k_p=100 s⁻² and k_v=20 s⁻¹','k_p=400 s⁻² and k_v=40 s⁻¹','k_p=10 s⁻² and k_v=20 s⁻¹','k_p=100 s⁻² and k_v=10 s⁻¹'],0,'The nominal natural frequency is 10 rad/s, so k_p=10² and k_v=2×10.',['This follows both design choices.','This sets the natural frequency at the resonance.','This fails to square the natural frequency.','This gives only half the critical damping coefficient.'],typ='numerical')
b.add(682,'distributed-flexibility','Interpret the equivalent mass and inertia factors','How should the diagram’s m_eff=0.23m and I_eff=0.33I be used?', ['As equivalent parameters for the depicted deformation models, not universal factors for all links and boundary conditions','As universal multipliers that apply to every rigid and flexible robot part','As instructions to change the material’s actual mass and inertia','As gear-ratio formulas independent of deformation shape'],0,'Equivalent modal parameters depend on the modeled shape and constraints; the slide gives factors for its illustrated approximations.',['This preserves the model-specific scope.','Different structures and modes have different equivalent parameters.','An equivalent model does not physically remove material.','These are flexibility approximations, not gearing relations.'],typ='diagram',assumptions=['Do not generalize the displayed factors beyond the illustrated approximation.'])
b.add(682,'distributed-flexibility','Compute the flexible-link frequency and check the printed hertz value','With link mass 4.347 kg, equivalent mass 0.23m and stiffness 3600 N/m, which frequency pair is consistent with the model to the displayed precision?', ['Approximately 60 rad/s and 9.55 Hz','Approximately 60 rad/s and 9.7 Hz','Approximately 9.55 rad/s and 60 Hz','Approximately 3600 rad/s and 573 Hz'],0,'The equivalent mass is 0.99981 kg, giving about 60.0057 rad/s and 9.5502 Hz; even the rounded 60 rad/s converts to about 9.55 Hz, not 9.7.',['This follows both the square-root model and conversion by 2π.','The printed 9.7 Hz does not follow from the given values.','This exchanges angular frequency and cycles per second.','This treats stiffness itself as an angular frequency.'],typ='source-reconciliation',conflict='Physical page 682 reports 60 rad/s as 9.7 Hz, but conversion of the displayed values gives about 9.55 Hz.',formulas=[formula('m_eff=0.23m; ω_res=√(k/m_eff); f_res=ω_res/(2π)',{'m_eff':'equivalent moving mass','m':'link mass','k':'equivalent stiffness','ω_res':'angular resonance frequency','f_res':'cyclic resonance frequency'},{'m_eff,m':'kg','k':'N/m','ω_res':'rad/s','f_res':'Hz'})],steps=['Compute 0.23×4.347=0.99981 kg.','Compute sqrt(3600/0.99981)≈60.0057 rad/s.','Divide by 2π to obtain approximately 9.5502 Hz.'])
b.add(683,'partitioned-joint','Match the nominal joint controller components','For J θddot+B θdot=τ, matched α=J, β=B θdot, and e=θ_d−θ, which partitioned controller gives eddot+k_v edot+k_p e=0 without disturbance?', ['τ=α(θ_d_ddot+k_v edot+k_p e)+β','τ=α(θ_d_ddot−k_v edot−k_p e)−β','τ=(θ_d_ddot+k_v edot+k_p e)/α−β','τ=αθ_d+Bθ without derivatives or error'],0,'Substitution cancels the modeled damping and yields θddot=θ_d_ddot+k_v edot+k_p e, which gives the stated error equation.',['This has the matching cancellation and error signs.','This reverses stabilizing error feedback and damping compensation.','This uses the inertia scaling and damping sign incorrectly.','This does not implement the stated tracking acceleration.'],typ='derivation',assumptions=['J and B match the actual constants, and no external disturbance is present.'],steps=['Substitute τ into J θddot+B θdot=τ.','Cancel B θdot and divide by J.','Use eddot=θ_d_ddot−θddot.'])
b.add(683,'maximum-inertia-qualification','Check the effect of using maximum rather than actual inertia','Let α=J_max but actual inertia be J, with damping canceled exactly and ρ=α/J; which error equation follows for the same partitioned controller?', ['eddot+ρk_v edot+ρk_p e=(1−ρ)θ_d_ddot','eddot+k_v edot+k_p e=0 for every J without any qualification','ρeddot+k_v edot+k_p e=(ρ−1)θ_d','eddot−ρk_v edot−ρk_p e=0 for every desired acceleration'],0,'The actual acceleration equals ρ(θ_d_ddot+k_v edot+k_p e), so subtracting it from desired acceleration yields the stated mismatch equation.',['This preserves the inertia ratio in both gains and feedforward mismatch.','Unit coefficients require matched inertia or an explicit lumped-mismatch term.','This uses desired position instead of acceleration and scales the wrong terms.','This reverses the error-feedback signs and drops the feedforward mismatch.'],typ='source-reconciliation',conflict='The slide sets α=I_max+η²I_m, then prints a unit-coefficient normalized error equation without explicitly showing mismatch when actual I differs.',assumptions=['Define J=I+η²I_m, α=I_max+η²I_m and ρ=α/J>0; damping is exactly compensated and external torque is absent.'],steps=['Write θddot=ρ(θ_d_ddot+k_v edot+k_p e).','Substitute eddot=θ_d_ddot−θddot and rearrange.'])
b.add(683,'disturbance-units','Normalize a physical opposing disturbance torque','For J θddot+B θdot=τ−d and matched model cancellation, what appears on the right of eddot+k_v edot+k_p e?', ['d/J, in rad/s²','d, in N·m without any inertia normalization','Jd, in N·m times kg·m²','−d/J, for the stated opposing-torque and error signs'],0,'An opposing torque reduces actual acceleration by d/J, so e=θ_d−θ acquires a positive d/J term.',['This has the correct sign and normalized units.','A physical torque cannot directly equal angular acceleration without normalization.','This multiplies by inertia instead of dividing.','This would fit the opposite disturbance or error convention.'],typ='source-reconciliation',conflict='The source writes τ_dist on an acceleration-level normalized error equation; a physical torque must be normalized by effective inertia, with its sign specified.',assumptions=['J>0, e=θ_d−θ, and positive d is an opposing physical load torque.'],formulas=[formula('eddot+k_v edot+k_p e=d/J',{'e':'desired minus actual load angle','k_v,k_p':'normalized velocity and position gains','d':'opposing physical disturbance torque','J':'effective load-coordinate inertia'},{'e':'rad','k_v':'s⁻¹','k_p':'s⁻²','d':'N·m','J':'kg·m²','d/J':'rad/s²'})])
b.add(684,'joint-feedback-blocks','Read the full joint-control signal path','Which order follows the forward path of the source’s feedback diagram?', ['Controller → motor driver → DC motor → joint/link → measured angle','Encoder → joint/link → desired angle → motor driver → controller output','Controller → measured angle → encoder → motor driver → desired angle','Motor driver → reference generator → encoder → mechanical link → controller input only'],0,'The forward chain converts a control error into electrical drive and mechanical motion, while the encoder returns an angle measurement to the comparison point.',['This follows the visible blocks.','This reverses and mixes the feedback and command paths.','This places the output measurement before the actuator.','This does not match the pictured forward sequence.'],typ='diagram',difficulty='easy')
b.add(684,'joint-feedback-blocks','Separate a PID block label from demonstrated simulation code','What can the diagram’s PID label establish about the later Python examples?', ['It illustrates a possible controller block, but the later constant-torque ODE must be inspected separately before claiming PID control is implemented','It proves that every later solve_ivp call implements all three PID terms','It proves that an encoder is read from physical hardware by the printed code','It proves that the simulated torque is continuously adjusted from desired-position error'],0,'A schematic label is not executable implementation evidence; the shown motor examples use specified torque and ODE integration, not a demonstrated PID loop.',['This keeps architecture separate from code evidence.','A solver call alone supplies no proportional, integral or derivative feedback.','The later code contains no physical encoder interface.','That requires an error-dependent control law absent from the constant-torque examples.'],typ='scenario')
